require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','receptionist','trainer']);$bid=current_branch_id();$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='renew'&&in_array(user()['role'],['super_admin','manager','receptionist'])){$plan=(int)$_POST['plan_id'];$p=query_one('SELECT * FROM membership_plans WHERE id=?',[$plan]);$m=query_one('SELECT * FROM members WHERE id=? AND branch_id=?',[$id,$bid]);if($m&&$p){$start=(strtotime($m['membership_end'])>=strtotime(date('Y-m-d')))?date('Y-m-d',strtotime($m['membership_end'].' +1 day')):date('Y-m-d');$end=date('Y-m-d',strtotime('+'.(int)$p['duration_months'].' months',strtotime($start)));$discount=max(0,(float)($_POST['discount']??0));$subtotal=max(0,(float)$p['price']-$discount);$taxRate=max(0,(float)setting('tax_percent','0'));$tax=$subtotal*($taxRate/100);$amount=$subtotal+$tax;db()->beginTransaction();try{db()->prepare("UPDATE members SET membership_plan_id=?,membership_start=?,membership_end=?,status='active' WHERE id=?")->execute([$plan,$start,$end,$id]);$ref='REN-'.date('ymdHis').'-'.$id;db()->prepare("INSERT INTO payments(branch_id,member_id,amount,method,payment_type,reference_no,payment_date,status,note,created_by) VALUES(?,?,?,?,?,?,CURDATE(),'paid',?,?)")->execute([$bid,$id,$amount,$_POST['method']??'Cash','Membership',$ref,trim(($discount>0?'Discount '.money($discount).'. ':'').($taxRate>0?'Tax '.$taxRate.'% = '.money($tax):''))?:null,user()['id']]);$payId=(int)db()->lastInsertId();db()->commit();audit_log('membership.renewed','member',$id,'Renewed to '.$p['name'].'; payment '.$ref);flash('success','Membership renewed and payment recorded.');redirect('app/payment_receipt.php?id='.$payId);}catch(Throwable $e){db()->rollBack();flash('danger','Renewal failed.');redirect('app/member_view.php?id='.$id);}}}
if($action==='freeze'&&in_array(user()['role'],['super_admin','manager'])){db()->prepare("UPDATE members SET status='frozen' WHERE id=? AND branch_id=?")->execute([$id,$bid]);audit_log('membership.frozen','member',$id,'Membership frozen');flash('warning','Membership frozen.');redirect('app/member_view.php?id='.$id);}
if($action==='unfreeze'&&in_array(user()['role'],['super_admin','manager'])){db()->prepare("UPDATE members SET status='active' WHERE id=? AND branch_id=?")->execute([$id,$bid]);audit_log('membership.unfrozen','member',$id,'Membership reactivated');flash('success','Membership reactivated.');redirect('app/member_view.php?id='.$id);}
if($action==='metric'&&in_array(user()['role'],['super_admin','manager','trainer'])){$h=(float)($_POST['height_cm']??0);$w=(float)$_POST['weight_kg'];$m=query_one('SELECT height_cm FROM members WHERE id=?',[$id]);$h=$h?:((float)$m['height_cm']);$bmi=$h>0?$w/(($h/100)**2):null;db()->prepare('INSERT INTO body_metrics(member_id,recorded_on,weight_kg,body_fat,bmi,waist_cm,notes) VALUES(?,CURDATE(),?,?,?,?,?)')->execute([$id,$w,$_POST['body_fat']?:null,$bmi,$_POST['waist_cm']?:null,trim($_POST['notes']??'')]);db()->prepare('UPDATE members SET weight_kg=? WHERE id=?')->execute([$w,$id]);audit_log('member.metric','member',$id,'Body progress metric recorded');flash('success','Progress metric saved.');redirect('app/member_view.php?id='.$id);}}
$m=query_one("SELECT m.*,p.name plan_name,p.price,t.name trainer_name FROM members m LEFT JOIN membership_plans p ON p.id=m.membership_plan_id LEFT JOIN trainers t ON t.id=m.trainer_id WHERE m.id=? AND m.branch_id=?",[$id,$bid]);if(!$m){http_response_code(404);exit('Member not found');}if(user()['role']==='trainer'){$myTrainerId=(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0);if((int)$m['trainer_id']!==$myTrainerId){http_response_code(403);exit('403 — This member is not assigned to your trainer account.');}}
$att=query_all('SELECT * FROM attendance WHERE member_id=? ORDER BY check_in DESC LIMIT 10',[$id]);$pay=query_all('SELECT * FROM payments WHERE member_id=? ORDER BY payment_date DESC,id DESC LIMIT 10',[$id]);$metrics=query_all('SELECT * FROM body_metrics WHERE member_id=? ORDER BY recorded_on ASC',[$id]);$plans=query_all("SELECT * FROM membership_plans WHERE status='active' ORDER BY price");$workouts=query_all('SELECT w.*,t.name trainer_name FROM workout_plans w LEFT JOIN trainers t ON t.id=w.trainer_id WHERE w.member_id=? ORDER BY w.created_at DESC',[$id]);
$diets=query_all('SELECT d.*,t.name trainer_name FROM diet_plans d LEFT JOIN trainers t ON t.id=d.trainer_id WHERE d.member_id=? ORDER BY d.created_at DESC LIMIT 3',[$id]);
$visits30=(int)query_value('SELECT COUNT(*) FROM attendance WHERE member_id=? AND check_in>=DATE_SUB(NOW(),INTERVAL 30 DAY)',[$id]);$paidTotal=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE member_id=? AND status='paid'",[$id]);$effective=strtotime($m['membership_end'])<strtotime(date('Y-m-d'))?'expired':$m['status'];$pageTitle=$m['first_name'].' '.$m['last_name'];include __DIR__.'/../includes/header.php'; ?>
