<?php $labels=array_column($metrics,'recorded_on');$weights=array_map(fn($x)=>(float)$x['weight_kg'],$metrics);$pageScript='<script>new Chart(document.getElementById("progressChart"),{type:"line",data:{labels:'.json_encode(array_map(fn($d)=>date('d M',strtotime($d)),$labels)).',datasets:[{label:"Weight kg",data:'.json_encode($weights).',borderColor:"#b7ff4a",backgroundColor:"rgba(183,255,74,.08)",fill:true,tension:.35}]},options:{maintainAspectRatio:false,plugins:{legend:{labels:{color:"#8f98a6"}}},scales:{x:{ticks:{color:"#77818d"},grid:{display:false}},y:{ticks:{color:"#77818d"},grid:{color:"rgba(255,255,255,.05)"}}}}});</script>';include __DIR__.'/../includes/footer.php'; ?>